Boolean can_usr_tx( Can_Dev_Id dev_id , Can_Msg *can_msg , Boolean do_it_fast , TskTimeout timeout )
{
    if( can_usr[ dev_id ].bus_off_ind ) return TRUE ; 
    
    if( !do_it_fast && can_usr[dev_id].tx_use_buffer )
    {    
        if( !pipe_insert( can_usr[dev_id].tx_pipe , can_msg , timeout )  )
        {
             TRACE_CAN_USR("\n\r[CAN_USR_TX : BUFFER FULL] --DEVICE:%d \n\r" , dev_id ); 

             can_usr_err_add( (dev_id == CAN_DEV_0) ? CAN_USR_ERR_DEV0_TX_PIPE_FULL : CAN_USR_ERR_DEV1_TX_PIPE_FULL );
             
             return FALSE ; 
        }
        
        return TRUE ;         
    }
    else
    {                   
        if( !can_usr_tx_normal( dev_id , can_msg , timeout))
        {
            TRACE_CAN_USR("[CAN_DEV_%d TX FAST ERROR]\n\r" , dev_id );              

            can_usr_err_add( (dev_id == CAN_DEV_0) ? CAN_USR_ERR_DEV0_TX_SYNC_TIMEOUT : CAN_USR_ERR_DEV1_TX_SYNC_TIMEOUT );

            return FALSE ;
        }
    }
    
    return TRUE ; 
}

